// The tasks-usage-fold work step, and the whole task: no agent phase.
//
// It holds NO counting logic: the counting, the folding and the reads live in its
// siblings. This file is the I/O shell:
//
//   1. read the prior file from the BASE TIP — never the working tree, which may be
//      sitting on another task's branch;
//   2. list the scheduler's and the executor's completed runs past
//      `runsFoldedThrough`, and for each read its jobs (the billed minutes) and, for
//      a scheduler tick, its log (the cost record a tick has nowhere else to leave);
//   3. list the work items that CLOSED past `queueFoldedThrough` and read each one's
//      timeline — its outcome, the parks it collected, the four latencies its label
//      events answer, and the executor's cost record riding its comments;
//   4. fold: hour rows over the last three days, day rows over the last month, week
//      rows advanced past `foldedThrough`;
//   5. deliver the folded usage file, and
//      open NOTHING when the recompute is byte-identical apart from its stamp.
//
// THE API BUDGET, which is the reason the reads are shaped as they are. Per fold:
// two run listings, flat; one jobs listing per run this fold has not seen; at most
// four job-log reads (two scheduler ticks a day, at most two jobs each); one issues
// listing page; and one timeline read per item closing for the first time. On this
// repo's own cadence — two ticks a day, a quiet queue — the run half of that is
// under ten calls a day, which a test asserts by counting the fetches a
// representative day makes.
//
// The aggregate lives under `.claudinite/usage/`, beside the repo's other rolling
// records, where the vendoring refresh never reaches.

import { readFileSync } from 'node:fs';
import { baseTip, readAt, readRollingAt, remoteUrl } from '../../public/delivery.mjs';
import { AUTOMERGE_TRAILER } from '../../src/contract/merge-policy.mjs';
import {
  encodeTasksUsageFile, decodeTasksUsageFile, renderTasksUsageFile, withoutStamp, TASKS_USAGE_PATH, LEGACY_TASKS_USAGE_PATH,
} from '../../src/items/tasks-usage-format.mjs';
import { foldTasksUsage } from './fold-tasks-usage.mjs';
import { makeReader, readRunCosts } from './read-run-costs.mjs';
import { readClosedItems } from './read-items.mjs';
import { settingsPath } from '../../../../engine/settings-file.mjs';


const PR_BRANCH_PREFIX = 'claudinite/tasks-usage-fold';
const PACK_ID = 'claudinite-tasks';

// The run's own logger, under the task's name and its item. Module-level because the
// helpers below log too; `worker` takes the one the runner built.
let log = console.log;

// What a minute of Actions costs this repo, from the pack's own config. UNSET IS
// NOT ZERO: a public repo bills nothing and a private one bills something, and a
// fold that wrote `spend: 0` for the second would be stating a figure nobody gave
// it. Absent, no row in the file carries a spend at all and a reader says so.
export function minuteRateFrom(config, packId = PACK_ID) {
  const rate = config?.packConfig?.[packId]?.actionsMinuteRate;
  return typeof rate === 'number' && Number.isFinite(rate) && rate >= 0 ? rate : null;
}

export async function worker({ root, repo, token, defaultBranch, automerge, deliver, log: runLog }) {
  log = runLog;
  const base = defaultBranch ?? 'main';
  const remote = remoteUrl(repo, token);

  let config = {};
  try { config = JSON.parse(readFileSync(settingsPath(root), 'utf8')); } catch { /* no declaration */ }
  const minuteRate = minuteRateFrom(config);
  if (minuteRate === null) log('no `actionsMinuteRate` in this pack\'s config — the file records minutes and no spend');

  const baseSha = baseTip(root, remote, base);
  const rolling = readRollingAt(root, baseSha, TASKS_USAGE_PATH, LEGACY_TASKS_USAGE_PATH);
  let prior = {};
  try { prior = decodeTasksUsageFile(JSON.parse(rolling.text ?? '{}')); } catch { /* unparsable → refold */ }

  const now = new Date().toISOString();
  const reader = makeReader({ token });

  // Each source is INDEPENDENTLY fail-soft: one that cannot be read costs its own
  // rows this run and leaves its own watermark where it was, so the next fold
  // retries exactly what it missed.
  const runs = await readRunCosts({ reader, repo, since: prior.runsFoldedThrough ?? null, now });
  if (runs.error) log(`${runs.error} — the run and cost rows are unchanged this run`);
  if (runs.truncated) log('more runs are waiting than one fold reads — the watermark stops at the last one measured');

  const items = await readClosedItems({
    reader, repo, since: prior.queueFoldedThrough ?? null, now,
    schedulerRuns: runs.runs.filter((r) => r.workflow === 'scheduler'),
  });
  if (items.error) log(`${items.error} — the outcome, park and latency rows are unchanged this run`);

  const today = now.slice(0, 10);
  const text = renderTasksUsageFile(encodeTasksUsageFile(foldTasksUsage({
    prior,
    today,
    now,
    generated: now,
    minuteRate,
    runs: runs.runs,
    runsFoldedThrough: runs.watermark,
    items: items.records,
    queueFoldedThrough: items.watermark,
  })));

  // Compared WITHOUT the freshness stamp, which moves every run by construction: a
  // day on which nothing ran must still open nothing.
  const landed = readAt(root, baseSha, TASKS_USAGE_PATH);
  if (landed !== null && withoutStamp(landed) === withoutStamp(text)) {
    log(`${runs.runs.length} run(s) and ${items.records.length} closed item(s) folded — recompute is byte-identical, nothing to deliver`);
    return;
  }

  const pr = await deliver({
    stamp: today, branchPrefix: PR_BRANCH_PREFIX,
    files: { [TASKS_USAGE_PATH]: text },
    moves: rolling.moves,
    message: `Claudinite: fold tasks usage\n\n${AUTOMERGE_TRAILER}: ${automerge}`,
    title: 'Claudinite: tasks usage fold',
    body: [
      `Regenerated \`${TASKS_USAGE_PATH}\` from this repo's scheduler and executor run`,
      "listings, each run's jobs, the cost records those runs printed, and the work",
      'items that have closed since the last fold.',
      '',
      'Per day and per workflow: runs, jobs, billed minutes and — only where this',
      "pack's config carries `actionsMinuteRate` — the spend they imply. Per run: the",
      'API calls it made and its wall time per phase. Per task: what its occurrences',
      'came to, the parks they collected, and the four latency samples their label',
      'events answer.',
      '',
      'Every tier is appended once past its own watermark; a recompute that differs',
      'only in its `generated` stamp opens no pull request at all. Machine-written —',
      'never hand-edit it.',
    ].join('\n'),
  });
  log(`${runs.runs.length} run(s) and ${items.records.length} closed item(s) folded — `
    + `${pr.reused ? 'updated' : 'opened'} PR ${pr.number !== null ? `#${pr.number}` : `on ${pr.branch}`}`
    + `${pr.merged ? ' (landed)' : pr.delivery === 'review' ? ' (left for review)' : ''}`);
}
// tasks-usage-fold's own precondition term.
//
// The fold's trigger is MOVEMENT IN THE MACHINERY — a scheduler tick or an executor
// run that this file has not counted yet — and no built-in term can say that: every
// movement condition reads the project's commits, issues, pull requests and
// captures, and a repo whose only activity is its own queue is silent by all four.
//
// What the term reads instead is the file's OWN WATERMARK, which is the cheapest
// honest evidence there is: `runsFoldedThrough` advances on every fold that read a
// run, so a mark still standing before the scheduler's most recent anchor means at
// least one tick has come and gone unfolded. That is the mark's own movement rather
// than standing state — it flips false the moment a fold catches up, and true again
// at the next tick — and it costs no API call at all, which matters on a term asked
// at every tick of every day.
//
// WHAT IT CANNOT SEE, stated rather than implied: it does not know how MANY runs are
// waiting, only that the mark is behind. A repo whose scheduler has stopped
// entirely is not asked at all, so there is nothing for this term to decline there.

import { readFileSync } from 'node:fs';
import { mostRecentAnchor } from '../../src/items/anchors.mjs';
import { decodeTasksUsageFile, TASKS_USAGE_PATH, LEGACY_TASKS_USAGE_PATH } from '../../src/items/tasks-usage-format.mjs';

// The mark the last fold left, read from the checkout the run holds. Null for a repo
// that has never folded — which is movement by definition, since everything its
// machinery has ever done is unread.
export function foldedThroughAt(root) {
  for (const path of [TASKS_USAGE_PATH, LEGACY_TASKS_USAGE_PATH]) {
    try {
      return decodeTasksUsageFile(JSON.parse(readFileSync(`${root}/${path}`, 'utf8'))).runsFoldedThrough;
    } catch { /* not at this path - the file may not have moved yet */ }
  }
  return null;
}

export const terms = {
  'runs-since-fold': {
    signals: [],
    holds(_signals, { now }) {
      // The scheduler and the executor both run with the checkout as their working
      // directory, and the fold's own worker takes the same root the same way.
      const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
      const mark = foldedThroughAt(root);
      if (!mark) return { holds: true, reason: 'nothing has been folded yet — every run this repo has made is uncounted' };
      const at = mostRecentAnchor('daily', now).toISOString();
      return mark < at
        ? { holds: true, reason: `runs are folded through ${mark}, before this UTC day opened at ${at}: the machinery has run since` }
        : { holds: false, reason: `runs are folded through ${mark}, inside the UTC day that opened at ${at}: nothing has run since the last fold` };
    },
  },
};
# Tasks usage fold — what the machinery itself cost

**This task runs no agent.** It is `agent_model: none` with `code_work: node worker.mjs`, so the whole pass is the deterministic [`worker.mjs`](worker.mjs) the executor runs as code-work, which calls the counting and folding core beside it ([`fold-tasks-usage.mjs`](fold-tasks-usage.mjs)). This file is the human-facing record of what that worker does.

## Two files, and why this is not the other one

[`usage-fold`](../usage-fold/README.md) folds what this repo's **sessions** did — skill loads, tokens, check findings, what landed in git. This one folds what the **machinery** did: how often the scheduler and the executor ran, what those runs were billed, what they spent in API calls and wall time, and what each occurrence of each task came to.

The split is by **source**, not by subject. The session fold's numbers come out of capture files it re-reads for free off a local branch; every source behind this one is a rate-limited REST listing read past a watermark. Keeping them in one file would mean one source's outage degrading the other's rows, one cadence serving two very different read costs, and a single watermark standing for two clocks.

What they share is their discipline, deliberately — the same three tiers, the same per-source fail-soft, the same rule that **an absent source leaves no key, never a zero** — and the readers, where one already reads the source: this fold's run listings are [`packs/claudinite-tasks/tasks/usage-fold/read-runs.mjs`](../usage-fold/read-runs.mjs)'s, and its task-and-park decoding is [`packs/claudinite-tasks/tasks/usage-fold/read-queue.mjs`](../usage-fold/read-queue.mjs)'s.

## What the file carries

`.claudinite/usage/task-runs-and-costs.json`, per hour, per day and per week:

- **Per workflow** (`scheduler`, `executor`) — `runs`, `jobs`, `minutesBilled`, and `spend`. Actions bills per **job**, not per run, so a run's minutes are the sum over its jobs of each job's wall time rounded up to a whole minute, and the two counts are kept apart. `spend` exists only where this pack's config carries `actionsMinuteRate`: unset leaves **no key at all**, because a public repo bills nothing and a private one bills something, and a zero would be a claim nobody made. The rate every figure was priced at is written into the file beside them, so a rate changed later cannot silently re-price rows frozen under the old one.
- **Per run** — `apiCalls` and the wall milliseconds of each phase (`list`, `ask`, `drain` for a tick; `pick`, `claim`, `code-work`, `hand-off`, `converge` for an executor run), from the `claudinite-run-cost` record every run prints. The format is [`packs/claudinite-tasks/src/items/run-record.mjs`](../../src/items/run-record.mjs)'s, beside the two execution records; the API calls are counted at the GitHub port itself, which is the only place every call passes through.
- **Per task** — what its occurrences came to (`done`, `delivered`, `obsolete`, `none`), the parks they collected by kind, and four **latency samples** off each closed item's own label events: tick→item, item→pick, pick→hand-off, hand-off→converge. Samples, never quantiles: a week's p50 is not derivable from its days', so the file carries what a reader needs to take the quantile over whatever window it is drawing. A slot whose far end never happened — an agentless item has no hand-off — is absent, which is not a latency of zero.

## Where a run's cost record is read from

A **scheduler tick owns no work item**, so the record it printed exists nowhere but its job log, and the fold reads it there. That read is what the cadence buys: the scheduler fires twice a day, at most two of its runs have their log read per fold, and at most two jobs are opened per run — so the log reads are bounded at four whatever else happened.

An **executor run has items**, so it writes its record where the record survives Actions retention: onto every item it settles, in the same fenced block as the execution record. One run therefore leaves several snapshots of one record, each a reading of counters that only ever grow, and the fold keys them by run id and keeps the **largest** — the run's total as of its last item. Under-counting is one-directional by construction, as every other floor in these two files is.

## The API budget

Stated here because it is the reason the reads are shaped as they are. Per fold:

- two run listings, flat, however many runs are in the window;
- one jobs listing per run this fold has not seen;
- at most four job-log reads;
- one issues listing page, plus one **timeline** read per item closing for the first time — one read, not two, because the timeline carries the labelings, the comments and the close together, which is exactly the three things this fold wants off an item.

On this repo's own cadence — two ticks a day and the executor runs a quiet queue dispatches — the run half of that is under ten calls a day, and the task's test asserts it by counting the fetches a representative day makes. `MAX_RUN_READS` is the runaway guard rather than the budget: a day that somehow produced hundreds of runs stops at the cap, leaves the watermark at the last run measured, and says so.

## Every tier is appended once

This is the one place the discipline differs from the session fold's, and it is worth stating plainly: that file recomputes its day rows from capture files, so a counting fix heals its whole visible window. **Nothing here is recomputed.** Every source is a watermarked listing, a run or an item is folded on the one pass that first sees it, and a counting bug fixed later applies from the fix forward.

Appending is safe because each fact is settled once seen — a completed run's start and conclusion do not move, a closed item's outcome label is written at convergence and is never moved — and both watermarks are monotone over those facts, which is the whole exactly-once mechanism. No ingest ledger.

Two maps do not reach the week tier on the same terms as the rest. A week's keys are frozen forever, so `runCosts` — keyed by run id, unique per occurrence — is dropped there and its numbers survive as the week's own scalars; per-run detail answers "what did this tick cost", which nobody asks of a week last February. `latency` is kept, unique keys and all, because the samples *are* the week-level answer.

## When it runs

Daily, and only when the machinery has moved: [`preconditions.mjs`](preconditions.mjs)'s `runs-since-fold` holds while the file's own `runsFoldedThrough` still stands before the scheduler's most recent anchor. That is the mark's own movement rather than standing state — it goes false the moment a fold catches up and true again at the next tick — and it costs no API call, which matters on a term asked at every tick.

## The file is GENERATED

Machine-written and never hand-edited. It lives under `.claudinite/local/` because that is the repo-owned area the vendoring refresh never touches, and `merge=ours` reaches it through the mount's own `.gitattributes`, whose `*GENERATED*` pattern the engine converges — so this file needed no attributes line of its own.

