git add -A packs && python3 - <<'EOF'
import subprocess,re
out=subprocess.run(['git','diff','--cached','-M','-U0','HEAD','--','packs/claudinite-tasks/tasks/usage-fold'],capture_output=True,text=True).stdout
cur=None;added={}
for l in out.splitlines():
    if l.startswith('+++ b/'): cur=l[6:]
    elif l.startswith('@@'):
        m=re.search(r'\+(\d+)(?:,(\d+))?',l); start=int(m.group(1)); n=int(m.group(2) or 1)
        added.setdefault(cur,set()).update(range(start,start+n))
tot=0
for f,lines in added.items():
    src=open(f).read().split('\n')
    for i in lines:
        if 0<i<=len(src) and '—' in src[i-1]:
            src[i-1]=src[i-1].replace('—','-'); tot+=1
    open(f,'w').write('\n'.join(src))
print(tot, {f:len(v) for f,v in added.items()})
EOF
git diff --stat

